"""The virtual clock: the Python half of the first evidence (docs/research/virtual-clock.md).

A generator's cell ``ts << 12 | seq`` is a hybrid logical clock for local events;
``Generator.observe`` is its receive rule. These tests prove, in Python and across the process
boundary to Go:

* ``vectors/clock.tsv`` (generated by the oracle) replays exactly: count, first, last, digest,
  observe verdicts, final virtual time. Go replays the same file, so the generators of the two
  runtimes are differential-tested, which a wall clock had made impossible;
* a fleet of generators with skewed clocks exchanging messages keeps every reply after the
  message it answers, and each node's virtual time within 2·skew of its own clock when messages
  take at least 1 ms;
* the textbook HLC receive rule (match the observed cell) breaks that order on the same fleet;
* one far-future id cannot drag the clock forward;
* a MIXED fleet, half Python generators and half Go generators in a separate process
  (go/internal/vclocknode), keeps the same order, and the two runtimes mint identical ids for
  identical programs.

The cross-process tests need the Go toolchain: they skip without it, and fail without it when
``BRD14_REQUIRE_CROSS=1`` (scripts/ci.sh sets it).
"""

from __future__ import annotations

import os
import select
import shutil
import subprocess
from collections.abc import Callable
from pathlib import Path
from typing import Protocol

import pytest

from brd14 import ErrorCode, Generator, InvalidIdError
from support import REPO, read_tsv

EPOCH_MS = 1_704_067_200_000
T0 = EPOCH_MS + 65_459_497_641  # the V-1 instant


class Clock:
    def __init__(self, ms: int) -> None:
        self.ms = ms

    def __call__(self) -> int:
        return self.ms


def fnv1a64(data: bytes) -> int:
    h = 0xCBF29CE484222325
    for b in data:
        h = ((h ^ b) * 0x100000001B3) & 0xFFFFFFFFFFFFFFFF
    return h


# ── vectors/clock.tsv ────────────────────────────────────────────────────────


def test_clock_vectors_replay_exactly() -> None:
    rows = read_tsv("clock.tsv")
    assert rows, "clock.tsv has no rows"
    for name, node, start, program, count, first, last, digest, verdicts, virtual in rows:
        clock = Clock(int(start))
        g = Generator(int(node), clock=clock)
        ids: list[int] = []
        seen: list[str] = []
        for tok in program.split(","):
            if tok[0] == "t":
                clock.ms = int(tok[1:])
            elif tok[0] == "m":
                for _ in range(int(tok[1:])):
                    ids.append(g.next())
            else:
                snow, ahead = tok[1:].split("~")
                seen.append("1" if g.observe(int(snow), int(ahead)) else "0")
        assert all(a < b for a, b in zip(ids, ids[1:])), name
        got = (
            str(len(ids)),
            str(ids[0]) if ids else "-",
            str(ids[-1]) if ids else "-",
            f"{fnv1a64(','.join(map(str, ids)).encode('ascii')):016x}",
            "".join(seen) or "-",
            str(g.virtual_ms),
        )
        assert got == (count, first, last, digest, verdicts, virtual), name


# ── a fleet with skewed clocks ───────────────────────────────────────────────


class Node(Protocol):
    def set_clock(self, ms: int) -> None: ...
    def mint(self) -> int: ...
    def observe(self, snow: int, max_ahead_ms: int) -> bool: ...
    def virtual_ms(self) -> int: ...


class PyNode:
    def __init__(self, node: int, ms: int) -> None:
        self.clock = Clock(ms)
        self.gen = Generator(node, clock=self.clock)

    def set_clock(self, ms: int) -> None:
        self.clock.ms = ms

    def mint(self) -> int:
        return self.gen.next()

    def observe(self, snow: int, max_ahead_ms: int) -> bool:
        return self.gen.observe(snow, max_ahead_ms)

    def virtual_ms(self) -> int:
        return self.gen.virtual_ms


class NaivePyNode(PyNode):
    """The textbook HLC receive rule on brd14: raise the cell to the observed cell. Test-only."""

    def observe(self, snow: int, max_ahead_ms: int) -> bool:
        cell = (snow >> 22) << 12 | (snow & 4095)
        with self.gen._lock:  # noqa: SLF001 — the model needs the cell
            self.gen._last = max(self.gen._last, cell)  # noqa: SLF001
        return True


class SplitMix64:
    def __init__(self, seed: int) -> None:
        self.s = seed

    def next(self) -> int:
        self.s = (self.s + 0x9E3779B97F4A7C15) & 0xFFFFFFFFFFFFFFFF
        z = self.s
        z = ((z ^ (z >> 30)) * 0xBF58476D1CE4E5B9) & 0xFFFFFFFFFFFFFFFF
        z = ((z ^ (z >> 27)) * 0x94D049BB133111EB) & 0xFFFFFFFFFFFFFFFF
        return z ^ (z >> 31)


def run_fleet(
    make: Callable[[int, int, int], Node], n: int, skew: int, min_delay: int, max_delay: int, steps: int
) -> tuple[int, int, int]:
    """(pairs, out-of-order replies, max drift ms). make(index, node, ms) builds node `index`."""
    rng = SplitMix64(0x0B4D14_00C10C)
    true_ms = T0
    offsets = [rng.next() % (2 * skew + 1) - skew for _ in range(n)]
    nodes = [make(i, i * 1023 // (n - 1), true_ms + offsets[i]) for i in range(n)]
    inflight: list[tuple[int, int, int]] = []  # (deliver_at, to, snow)
    pairs = violations = max_drift = 0
    for _ in range(steps):
        true_ms += rng.next() % 2  # 0 or 1 ms per step: many events share a millisecond
        for i, node in enumerate(nodes):
            node.set_clock(true_ms + offsets[i])
        due = [m for m in inflight if m[0] <= true_ms]
        inflight = [m for m in inflight if m[0] > true_ms]
        for _, to, snow in due:
            node = nodes[to]
            assert node.observe(snow, 1 << 40)
            reply = node.mint()
            pairs += 1
            violations += reply <= snow
            max_drift = max(max_drift, node.virtual_ms() - (true_ms + offsets[to]))
        src = rng.next() % n
        dst = rng.next() % (n - 1)
        dst += dst >= src
        delay = min_delay + rng.next() % (max_delay - min_delay + 1)
        inflight.append((true_ms + delay, dst, nodes[src].mint()))
    return pairs, violations, max_drift


def test_observe_orders_every_reply_after_its_message() -> None:
    pairs, violations, drift = run_fleet(lambda i, node, ms: PyNode(node, ms), 16, 50, 0, 20, 30_000)
    assert pairs > 29_000 and violations == 0, (pairs, violations)
    print(f"16 Python nodes, ±50 ms skew: {pairs} pairs, 0 out of order, max drift {drift} ms")


def test_the_textbook_receive_rule_breaks_the_order() -> None:
    pairs, violations, _ = run_fleet(lambda i, node, ms: NaivePyNode(node, ms), 16, 50, 0, 20, 30_000)
    assert violations > 0, "the fleet never produced a same-ms reply from a lower node"
    print(f"textbook rule: {violations} of {pairs} replies sort before the message they answer")


@pytest.mark.parametrize("skew", [0, 5, 50, 500])
def test_drift_stays_within_two_skews(skew: int) -> None:
    """Every id minted at true time t carries a ms <= t + skew when messages take >= 1 ms, and the
    receiver's clock reads >= t - skew: drift <= 2 * skew (docs/research/virtual-clock.md)."""
    _, violations, drift = run_fleet(lambda i, node, ms: PyNode(node, ms), 16, skew, 1, 20, 15_000)
    assert violations == 0
    assert drift <= 2 * skew, f"skew {skew}: drift {drift} > {2 * skew}"
    print(f"skew ±{skew} ms: max drift {drift} ms (bound {2 * skew})")


def test_a_far_future_id_cannot_drag_the_clock() -> None:
    g = Generator(5, clock=Clock(T0))
    before = g.virtual_ms
    far = (65_459_497_641 + 5_000) << 22
    assert g.observe(far, 1000) is False and g.virtual_ms == before
    assert g.observe(far, 10_000) is True and g.virtual_ms == T0 + 5_000
    nxt = g.next()
    assert nxt > far and nxt >> 22 == 65_459_497_641 + 5_001
    with pytest.raises(InvalidIdError) as ei:
        g.observe(1 << 63, 1 << 40)
    assert ei.value.code is ErrorCode.RANGE


# ── across the process boundary: Python and Go in one fleet ──────────────────


@pytest.fixture(scope="module")
def go_node_binary(tmp_path_factory: pytest.TempPathFactory) -> Path:
    go = shutil.which("go")
    if go is None:
        if os.environ.get("BRD14_REQUIRE_CROSS") == "1":
            pytest.fail("BRD14_REQUIRE_CROSS=1 but the Go toolchain is not on PATH")
        pytest.skip("Go toolchain not on PATH: the cross-runtime tests need go/internal/vclocknode")
    out = tmp_path_factory.mktemp("vclocknode") / "vclocknode"
    subprocess.run([go, "build", "-o", str(out), "./internal/vclocknode"], cwd=REPO / "go", check=True)
    return out


class GoProcess:
    """One go/internal/vclocknode process hosting several Go generators."""

    def __init__(self, binary: Path) -> None:
        self.p = subprocess.Popen(
            [str(binary)], stdin=subprocess.PIPE, stdout=subprocess.PIPE, text=True, bufsize=1
        )

    def ask(self, line: str) -> str:
        assert self.p.stdin is not None and self.p.stdout is not None
        self.p.stdin.write(line + "\n")
        # A lost answer must fail the test, not hang it (a missing flush did once).
        ready, _, _ = select.select([self.p.stdout], [], [], 10)
        assert ready, f"vclocknode did not answer {line!r} within 10 s"
        answer = self.p.stdout.readline().strip()
        assert answer, f"vclocknode gave no answer to {line!r} (exit {self.p.poll()})"
        return answer

    def close(self) -> None:
        assert self.p.stdin is not None and self.p.stdout is not None
        self.p.stdin.close()
        try:
            assert self.p.wait(timeout=10) == 0
        finally:
            self.p.stdout.close()


class GoNode:
    def __init__(self, proc: GoProcess, name: str, node: int, ms: int) -> None:
        self.proc, self.name = proc, name
        assert proc.ask(f"new {name} {node} {ms}") == "ok"

    def set_clock(self, ms: int) -> None:
        assert self.proc.ask(f"t {self.name} {ms}") == "ok"

    def mint(self) -> int:
        return int(self.proc.ask(f"m {self.name}"))

    def observe(self, snow: int, max_ahead_ms: int) -> bool:
        answer = self.proc.ask(f"o {self.name} {snow} {max_ahead_ms}")
        assert answer in ("0", "1"), answer
        return answer == "1"

    def virtual_ms(self) -> int:
        return int(self.proc.ask(f"v {self.name}"))


def test_a_mixed_python_and_go_fleet_keeps_causal_order(go_node_binary: Path) -> None:
    proc = GoProcess(go_node_binary)
    try:

        def make(i: int, node: int, ms: int) -> Node:
            return GoNode(proc, f"g{i}", node, ms) if i % 2 else PyNode(node, ms)

        pairs, violations, drift = run_fleet(make, 8, 50, 1, 20, 3_000)
    finally:
        proc.close()
    assert pairs > 2_900 and violations == 0, (pairs, violations)
    assert drift <= 2 * 50
    print(f"mixed fleet (4 Python + 4 Go nodes, ±50 ms): {pairs} pairs, 0 out of order, max drift {drift} ms")


def test_python_and_go_mint_identical_ids_for_identical_programs(go_node_binary: Path) -> None:
    rng = SplitMix64(0x0B4D14_0C0DE)
    proc = GoProcess(go_node_binary)
    try:
        for case in range(20):
            node = rng.next() % 1024
            now = T0 + rng.next() % 1_000_000
            py, go = PyNode(node, now), GoNode(proc, f"c{case}", node, now)
            for _ in range(400):
                r = rng.next() % 10
                if r < 5:
                    assert py.mint() == go.mint()
                elif r < 8:
                    now += rng.next() % 41 - 20  # steps both ways
                    py.set_clock(now)
                    go.set_clock(now)
                else:
                    snow = (now - EPOCH_MS + rng.next() % 201 - 100) << 22 | (rng.next() % (1 << 22))
                    assert py.observe(snow, 50) == go.observe(snow, 50)
                assert py.virtual_ms() == go.virtual_ms()
    finally:
        proc.close()
